import { Injectable, computed, inject, signal } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Router } from '@angular/router';
import { Observable, of } from 'rxjs';
import { map, catchError, tap, filter, take } from 'rxjs/operators';

export interface UserInfo {
  username: string;
  roles: string[];
}

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly TOKEN_KEY = 'jwt_token';
  private readonly API_URL = '/api'; // proxied to http://localhost:8082 in dev

  private http = inject(HttpClient);
  private router = inject(Router);

  private userSubject = signal<UserInfo | null>(null);

  /**
   * Tracks whether auth initialization has completed (success or failure).
   * Guards and AppComponent wait on this before making routing decisions.
   */
  private initializedSubject = signal(false);

  /** Readonly signals consumed by components and guards */
  public readonly user = this.userSubject.asReadonly();
  public readonly isAuthenticated = computed(() => this.userSubject() !== null);
  public readonly isInitialized = this.initializedSubject.asReadonly();

  constructor() {
    // Re-validate any persisted token on app startup (e.g. page refresh)
    const token = this.getToken();
    if (token) {
      this.validateWithBackend(token);
    } else {
      // No token at all — initialization is immediately complete
      this.initializedSubject.set(true);
    }
  }

  /** Returns the stored JWT, or null if absent */
  getToken(): string | null {
    return sessionStorage.getItem(this.TOKEN_KEY);
  }

  /**
   * Stores a new token received via SSO URL param and triggers backend validation.
   * Called by AppComponent after stripping ?token= from the URL.
   */
  setToken(token: string): void {
    sessionStorage.setItem(this.TOKEN_KEY, token);
    this.validateWithBackend(token);
  }

  /** Validates token against backend — sets user signal and marks initialization done */
  private validateWithBackend(token: string): void {
    const headers = new HttpHeaders({ Authorization: `Bearer ${token}` });

    this.http.get<UserInfo>(`${this.API_URL}/auth/validate`, { headers }).subscribe({
      next: (userInfo) => {
        this.userSubject.set(userInfo);
        this.initializedSubject.set(true);
        // Navigate to dashboard — guard will allow it since isAuthenticated() is now true
        this.router.navigate(['/dashboard']);
      },
      error: (err) => {
        console.warn('Token validation failed:', err.status);
        this.initializedSubject.set(true); // mark done even on failure
        this.logout();
      }
    });
  }

  /**
   * Returns an Observable that emits true/false once initialization is complete.
   * Used by authGuard to avoid acting before validation finishes.
   */
  waitForInitialization(): Observable<boolean> {
    if (this.isInitialized()) {
      return of(this.isAuthenticated());
    }
    // Poll the signal via an interval-free approach using a simple promise wrapper
    return new Observable<boolean>(observer => {
      const check = () => {
        if (this.isInitialized()) {
          observer.next(this.isAuthenticated());
          observer.complete();
        } else {
          setTimeout(check, 50);
        }
      };
      check();
    });
  }

  getDashboardData() {
    return this.http.get<any>(`${this.API_URL}/dashboard/data`);
  }

  logout(): void {
    sessionStorage.removeItem(this.TOKEN_KEY);
    this.userSubject.set(null);
    window.location.href = 'http://localhost:4200/login';
  }
}
